p='app/routes/app/profile.tsx'
s=open(p).read()
s=s.replace("""import { UpdateProfile }""","""import { ChangePassword } from '@/features/users/components/change-password';
import { UpdateProfile }""")
s=s.replace("""            <UpdateProfile />
""","""            <div className="flex gap-2">
              <ChangePassword />
              <UpdateProfile />
            </div>
""")
open(p,'w').write(s)

p='testing/mocks/handlers/users.ts'
s=open(p).read()
s=s.replace("""import {
  requireAuth,""","""import {
  hash,
  requireAuth,""")
s=s.replace("""export const usersHandlers""","""type PasswordBody = {
  currentPassword: string;
  newPassword: string;
};

export const usersHandlers""")
s=s.replace("""  http.delete(`${env.API_URL}/users/:userId`""","""  http.patch(`${env.API_URL}/users/password`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error || !user) {
        return HttpResponse.json(
          { message: error ?? 'Unauthorized' },
          { status: 401 },
        );
      }
      const { currentPassword, newPassword } =
        (await request.json()) as PasswordBody;

      // requireAuth returns the user without the password, so read the full record
      const storedUser = db.user.findFirst({
        where: {
          id: {
            equals: user.id,
          },
        },
      });

      if (!currentPassword || storedUser?.password !== hash(currentPassword)) {
        return HttpResponse.json(
          { message: 'The current password is incorrect' },
          { status: 400 },
        );
      }

      if (!newPassword || newPassword.length < 5) {
        return HttpResponse.json(
          { message: 'The new password must be at least 5 characters' },
          { status: 400 },
        );
      }

      db.user.update({
        where: {
          id: {
            equals: user.id,
          },
        },
        data: {
          password: hash(newPassword),
        },
      });
      await persistDb('user');
      return HttpResponse.json({ message: 'Password changed' });
    } catch (error) {
      return HttpResponse.json(
        {
          message: error instanceof Error ? error.message : 'Server Error',
        },
        { status: 500 },
      );
    }
  }),

  http.delete(`${env.API_URL}/users/:userId`""")
open(p,'w').write(s)
EOF
